import { test, expect } from "@playwright/test";

// Generated by One Touch E2E for BOK-21.
const BASE_URL = process.env.BASE_URL ?? "http://localhost:3000";

test.describe("ViewArticleOnWikipedia (api)", () => {
  test("TC-01 Happy path - Anonymous user searches for a valid topic and views the Wikipedia article", async ({ request }) => {
    const response = await request.get(BASE_URL);
    expect(response.status()).toBeLessThan(500);
  });
  test("TC-02 Happy path - Topic is discovered using search bar autocomplete suggestions", async ({ request }) => {
    const response = await request.get(BASE_URL);
    expect(response.status()).toBeLessThan(500);
  });
  test("TC-03 Negative - Submitting an empty search bar returns a blank search results page", async ({ request }) => {
    const response = await request.get(BASE_URL);
    expect(response.status()).toBeLessThan(500);
  });
  test("TC-04 Negative - Invalid / non-existent search text shows 'no results matching the query' message", async ({ request }) => {
    const response = await request.get(BASE_URL);
    expect(response.status()).toBeLessThan(500);
  });
  test("TC-05 Negative - Search text longer than 500 characters shows maximum length error message", async ({ request }) => {
    const response = await request.get(BASE_URL);
    expect(response.status()).toBeLessThan(500);
  });
  test("TC-06 Boundary - Search text of exactly 500 characters and exactly 501 characters", async ({ request }) => {
    const response = await request.get(BASE_URL);
    expect(response.status()).toBeLessThan(500);
  });
  test("TC-07 Negative - Search bar input containing only whitespace characters", async ({ request }) => {
    const response = await request.get(BASE_URL);
    expect(response.status()).toBeLessThan(500);
  });
});
